// src/components/AiCompanion.js
import React, { useState } from 'react';
import styled from 'styled-components';

const CompanionContainer = styled.div`
  margin: 20px 0;
  padding: 20px;
  border-radius: 8px;
  background-color: #e0f7fa;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
`;

const Question = styled.p`
  font-size: 1.2rem;
  margin-bottom: 10px;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 10px;
`;

const Button = styled.button`
  flex: 1;
  padding: 10px;
  border-radius: 5px;
  border: none;
  cursor: pointer;

  &:hover {
    opacity: 0.9;
  }

  ${({ yes }) =>
    yes
      ? `background-color: green; color: white;`
      : `background-color: red; color: white;`}
`;

const AiCompanion = ({ setPackagePrice }) => {
  const [step, setStep] = useState(0);
  const [budget, setBudget] = useState(null);

  const questions = [
    'Are you preparing for your first triathlon?',
    'Do you need a complete gear package?',
    'Do you have a budget in mind?',
  ];

  const handleYes = () => {
    if (step === 2) {
      const userBudget = prompt('Enter your budget:');
      setBudget(userBudget);
      setPackagePrice(userBudget);
    }
    setStep((prev) => prev + 1);
  };

  const handleNo = () => setStep((prev) => prev + 1);

  return (
    <CompanionContainer>
      <Question>{questions[step]}</Question>
      <ButtonGroup>
        <Button yes onClick={handleYes}>
          Yes
        </Button>
        <Button onClick={handleNo}>No</Button>
      </ButtonGroup>
    </CompanionContainer>
  );
};

export default AiCompanion;
